import { useEffect, useState } from 'react';

function readStoredTheme(): boolean {
  if (typeof window === 'undefined') return false;

  try {
    // Dark mode is default; only explicit "light" switches theme.
    return window.localStorage.getItem('theme') === 'light';
  } catch {
    return false;
  }
}

export function usePersistentTheme(): [boolean, () => void] {
  const [isLight, setIsLight] = useState<boolean>(false);

  useEffect(() => {
    setIsLight(readStoredTheme());
  }, []);

  const toggle = () => {
    setIsLight((prev) => {
      const next = !prev;
      try {
        window.localStorage.setItem('theme', next ? 'light' : 'dark');
      } catch {
        // noop in sandboxed environments
      }
      return next;
    });
  };

  return [isLight, toggle];
}
