import React from 'react';
import type { ThemeProps } from '../types';

export function Footer({ t }: ThemeProps) {
  return (
    <footer
      style={{
        borderTop: `1px solid ${t.border}`,
        background: t.bg,
        transition: 'background 0.35s, border-color 0.35s',
      }}
    >
      <div
        className='cv-inner'
        style={{
          padding: '24px 48px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
        }}
      >
        <span
          style={{
            fontSize: 11,
            color: t.text3,
            letterSpacing: '0.04em',
            fontFamily: 'DM Mono, monospace',
          }}
        >
          © 2026 Sanj Di. All rights reserved.
        </span>
        <span
          style={{
            fontSize: 11,
            color: t.text3,
            letterSpacing: '0.04em',
            fontFamily: 'DM Mono, monospace',
          }}
        >
          Built with Gatsby.js · Melbourne, AU
        </span>
      </div>
    </footer>
  );
}
